"""Smoke test for a Python interpreter cross-compiled for Android."""

import importlib
import platform
import sys
import sysconfig

print(sys.version)
print("machine:", platform.machine(), "platform:", sys.platform)
try:
    print("SOABI:", sysconfig.get_config_var("SOABI"))
except ImportError as e:
    # The sysconfig data module is generated by running the built interpreter,
    # which is not done when cross-compiling
    print("SOABI: unknown (sysconfig data not available:", e, ")")

# Modules that are expected to be available
required = ["math", "json", "re", "zlib", "decimal", "struct", "datetime", "select", "socket"]
# Modules that depend on third-party libraries that may not be available
optional = ["hashlib", "_ssl", "sqlite3", "_bz2", "_lzma", "_ctypes", "readline", "_curses"]

failed = []
for name in required + optional:
    try:
        importlib.import_module(name)
        print(f"  {name}: ok")
    except ImportError as e:
        print(f"  {name}: not available ({e})")
        if name in required:
            failed.append(name)

from decimal import Decimal
import zlib
assert str(Decimal(1) / Decimal(7)) == "0.1428571428571428571428571429"
assert zlib.decompress(zlib.compress(b"python" * 100)) == b"python" * 100

if failed:
    sys.exit(f"Required modules failed to import: {', '.join(failed)}")
print("Smoke test passed")
